#!/usr/bin/env node
/**
 * validate-design.mjs — Generic DS Token Validator
 *
 * Valida que os componentes Vue do projeto usam apenas cores, fontes e tokens
 * permitidos conforme dock-ds.config.json.
 *
 * Uso:
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/validate-design.mjs
 *   npm run validate:design
 *
 * Exit code 0 = tudo ok
 * Exit code 1 = violações encontradas
 */

import { readFileSync, readdirSync, statSync, existsSync } from 'fs';
import { join, relative } from 'path';

const CWD = process.cwd();

// === Load Config ===

function loadConfig() {
  const configPath = join(CWD, 'dock-ds.config.json');
  if (!existsSync(configPath)) {
    console.error('❌ dock-ds.config.json não encontrado na raiz do projeto.');
    console.error('   Rode: npx @dock-tech/shared-copilot-front-lib init');
    process.exit(1);
  }
  return JSON.parse(readFileSync(configPath, 'utf-8'));
}

const config = loadConfig();

// Colors allowlist (lowercase, without #)
const ALLOWED_COLORS = new Set(
  (config.tokens?.colors || []).map((c) => c.replace('#', '').toLowerCase())
);

// Fonts
const BANNED_FONTS = (config.tokens?.fonts?.banned || []).map((f) => f.toLowerCase());

// Build regex patterns for banned fonts
const BANNED_FONT_PATTERNS = BANNED_FONTS.map(
  (font) => new RegExp(`(?:font-family|font-\\[)[^;}"]*${font.replace(/\s+/g, '\\s*')}`, 'gi')
);

// === File Discovery ===

function getAllVueFiles(dir) {
  if (!existsSync(dir)) return [];
  const files = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const stat = statSync(full);
    if (stat.isDirectory() && entry !== 'node_modules' && entry !== '__tests__') {
      files.push(...getAllVueFiles(full));
    } else if (entry.endsWith('.vue') || entry.endsWith('.ts') || entry.endsWith('.css')) {
      files.push(full);
    }
  }
  return files;
}

// === Validators ===

function extractHexColors(content) {
  const regex = /#([0-9a-fA-F]{3,8})\b/g;
  const matches = [];
  let match;
  while ((match = regex.exec(content)) !== null) {
    matches.push({ hex: match[1].toLowerCase(), index: match.index });
  }
  return matches;
}

function normalizeHex(hex) {
  const value = hex.toLowerCase();
  if (value.length === 3) {
    return value[0] + value[0] + value[1] + value[1] + value[2] + value[2];
  }
  return value.slice(0, 6);
}

function extractFontViolations(content) {
  const issues = [];
  for (const pattern of BANNED_FONT_PATTERNS) {
    pattern.lastIndex = 0;
    let match;
    while ((match = pattern.exec(content)) !== null) {
      issues.push({ font: match[0].trim(), index: match.index });
    }
  }
  return issues;
}

function getLineNumber(content, index) {
  return content.substring(0, index).split('\n').length;
}

// === Contrast Check ===

function hexToRgb(hex) {
  const normalized = normalizeHex(hex);
  if (normalized.length !== 6) return null;
  return {
    r: parseInt(normalized.slice(0, 2), 16),
    g: parseInt(normalized.slice(2, 4), 16),
    b: parseInt(normalized.slice(4, 6), 16),
  };
}

function getRelativeLuminance({ r, g, b }) {
  const channel = (value) => {
    const n = value / 255;
    return n <= 0.03928 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
}

function getContrastRatio(fg, bg) {
  const fgRgb = hexToRgb(fg);
  const bgRgb = hexToRgb(bg);
  if (!fgRgb || !bgRgb) return null;
  const l1 = getRelativeLuminance(fgRgb);
  const l2 = getRelativeLuminance(bgRgb);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

function extractContrastWarnings(content) {
  const warnings = [];
  const classRegex = /class\s*=\s*(["'])([\s\S]*?)\1/g;
  const minContrast = config.validation?.contrastMinimum?.normalText || 4.5;
  let match;

  while ((match = classRegex.exec(content)) !== null) {
    const classValue = match[2];
    const textMatch = classValue.match(/text-\[#([0-9a-fA-F]{3,8})\]/);
    const bgMatch = classValue.match(/bg-\[#([0-9a-fA-F]{3,8})\]/);

    if (!textMatch || !bgMatch) continue;

    const ratio = getContrastRatio(textMatch[1], bgMatch[1]);
    if (ratio !== null && ratio < minContrast) {
      warnings.push({
        text: textMatch[1],
        bg: bgMatch[1],
        ratio: ratio.toFixed(2),
        line: getLineNumber(content, match.index),
      });
    }
  }
  return warnings;
}

// === Main ===

function main() {
  const srcDir = join(CWD, 'src');
  const files = getAllVueFiles(srcDir);

  if (files.length === 0) {
    console.log('⚠️  Nenhum arquivo .vue/.ts/.css encontrado em src/');
    process.exit(0);
  }

  let totalViolations = 0;
  let totalWarnings = 0;
  const report = [];

  console.log('🔍 Validando Design System tokens...\n');
  console.log(`   Config: dock-ds.config.json`);
  console.log(`   Cores permitidas: ${ALLOWED_COLORS.size}`);
  console.log(`   Fontes banidas: ${BANNED_FONTS.length}`);
  console.log(`   Arquivos: ${files.length}\n`);

  for (const file of files) {
    const content = readFileSync(file, 'utf-8');
    const rel = relative(CWD, file);
    const fileIssues = [];

    // Check colors
    if (ALLOWED_COLORS.size > 0) {
      const colors = extractHexColors(content);
      for (const { hex, index } of colors) {
        // Skip 3-char shorthand (often IDs, not colors)
        if (hex.length === 3) continue;

        const normalized = normalizeHex(hex);
        if (!ALLOWED_COLORS.has(normalized) && !ALLOWED_COLORS.has(hex)) {
          const line = getLineNumber(content, index);
          fileIssues.push({ type: 'color', hex, line, severity: 'error' });
          totalViolations++;
        }
      }
    }

    // Check fonts
    const fontIssues = extractFontViolations(content);
    for (const { font, index } of fontIssues) {
      const line = getLineNumber(content, index);
      fileIssues.push({ type: 'font', font, line, severity: 'error' });
      totalViolations++;
    }

    // Check contrast
    const contrastWarnings = extractContrastWarnings(content);
    for (const warn of contrastWarnings) {
      fileIssues.push({
        type: 'contrast',
        detail: `text #${warn.text} on bg #${warn.bg} = ${warn.ratio}:1`,
        line: warn.line,
        severity: 'warning',
      });
      totalWarnings++;
    }

    if (fileIssues.length > 0) {
      report.push({ file: rel, issues: fileIssues });
    }
  }

  // Output
  if (report.length === 0) {
    console.log('✅ Nenhuma violação encontrada. Tokens conformes ao DS!\n');
    process.exit(0);
  }

  console.log('─'.repeat(60));
  for (const { file, issues } of report) {
    console.log(`\n📄 ${file}`);
    for (const issue of issues) {
      const icon = issue.severity === 'error' ? '  ✗' : '  ⚠';
      if (issue.type === 'color') {
        console.log(`${icon} L${issue.line}: Cor #${issue.hex} não está no allowlist`);
      } else if (issue.type === 'font') {
        console.log(`${icon} L${issue.line}: Fonte banida: ${issue.font}`);
      } else if (issue.type === 'contrast') {
        console.log(`${icon} L${issue.line}: Contraste insuficiente — ${issue.detail}`);
      }
    }
  }

  console.log('\n' + '─'.repeat(60));
  console.log(`\n❌ ${totalViolations} violações, ${totalWarnings} avisos de contraste`);
  console.log('   Corrija as violações antes de abrir o PR.\n');

  // Exit with error only on hard violations
  process.exit(totalViolations > 0 ? 1 : 0);
}

main();
